function Modal({title,subtitle,children,onClose}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const prev=document.activeElement as HTMLElement;ref.current?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const items=ref.current?.querySelectorAll<HTMLElement>('button,input,select,a[href]');if(!items?.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};window.addEventListener('keydown',handler);return()=>{window.removeEventListener('keydown',handler);prev?.focus()}},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><div className="modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><Btn onClick={onClose} title="Close dialog"><X size={18}/></Btn></div>{children}</div></div>}
function NumberField({label,value,onChange,min=0,max=1800,step=.1,suffix}:{label:string;value:number;onChange:(n:number)=>void;min?:number;max?:number;step?:number;suffix?:string}){return <label className="number-field"><span>{label}</span><div><input type="number" aria-label={label} value={Number(value.toFixed(3))} min={min} max={max} step={step} onChange={e=>{const n=+e.target.value;if(Number.isFinite(n)&&n>=min&&n<=max)onChange(n)}}/>{suffix&&<small>{suffix}</small>}</div></label>}
function Slider({label,value,onChange,min=-12,max=12,unit=' dB',step=.5}:{label:string;value:number;onChange:(n:number)=>void;min?:number;max?:number;unit?:string;step?:number}){return <label className="slider-field"><span>{label}<b>{value>0&&min<0?'+':''}{value.toFixed(step<1?1:0)}{unit}</b></span><input type="range" aria-label={label} value={value} min={min} max={max} step={step} onChange={e=>onChange(+e.target.value)}/></label>}
