 function togglePlay(){if(playing){audioRef.current?.pause();setPlaying(false);return}if(!project.clips.length){notify('Add a song to the timeline or open the demo session.');return}if(playhead>=duration&&duration>0)seek(project.loop?.enabled?project.loop.start:0);if(renderedKey.current!==JSON.stringify(project)){renderMix();return}startAudioGraph();audioRef.current?.play().then(()=>setPlaying(true)).catch(e=>notify(e.message,true));}
